/**
 * The cost of content negotiation — rfcs/0001 §13.4, §18.6.
 *
 * `node benchmarks/negotiation/run.ts`
 *
 * Seven sections, three of which are CI gates.
 *
 *   1. **A route that declares one representation.** The familiar zero-cost
 *      gate (§9.4), against the generated bytes rather than a clock: a plain
 *      route must compile to exactly what it compiled before this feature
 *      existed, in a process where a negotiated route also exists.
 *   2. **What negotiation costs per request**, by the shape of the `Accept`
 *      header, in paired comparisons against the same route declared plainly.
 *      Five shapes, because they take five different paths through the matcher
 *      and only one of them parses anything.
 *   3. **Do the fast paths pay?** The three shortcuts ahead of the cache exist
 *      on the claim that real traffic is mostly "no header", "the exact type"
 *      and "a wildcard". If they are not measurably cheaper than parsing, they
 *      are three branches and a loop bought for nothing, and this section says
 *      so.
 *   4. **Does the cache pay?** Same question about the map. §13.4 asserts a
 *      cache is worth having; a benchmark is the only thing that can agree.
 *   5. **What a 406 costs**, against the 200 it would otherwise have been. The
 *      number here was expected to be small and is not, for the reason §28.8
 *      already records about the 404: it is the `Error`, not the negotiation.
 *   6. **The security gate.** A representation the client refused is never
 *      served, over every shape of offer list and every shape of hostile
 *      `Accept`. In a benchmark rather than only in the tests for the reason
 *      §11.4's gate is: "serve the first thing we have" is the fastest possible
 *      negotiation, and it is the shortcut an optimisation reaches for first.
 *   7. **The cache is bounded by attacker-chosen keys.** The key is a header.
 */
import {
  createApp, jsonSchema, registerMediaEncoder, makeNegotiator, selectOffer, offersOf,
  parseAccept, NEGOTIATION_CACHE_LIMIT,
  type Logger, type Representation,
} from '@erenthedeveloper0/zen-core'
import { ZenRouter, parsePath } from '@erenthedeveloper0/zen-router'

const pathParser = {
  parse: (path: string) => {
    const parsed = parsePath(path)
    return { path: parsed.path, segments: parsed.segments }
  },
}

const silent: Logger = (() => {
  const noop = () => {}
  const logger = { level: 'fatal' as const, child: () => logger, trace: noop, debug: noop, info: noop, warn: noop, error: noop, fatal: noop }
  return logger
})()

const JSON_MEDIA = 'application/json'
const CSV = 'text/csv'

registerMediaEncoder(CSV, (schema) => {
  const items = schema?.['items'] as Record<string, unknown> | undefined
  const columns = Object.keys((items?.['properties'] ?? {}) as Record<string, unknown>)
  return (value) => {
    const rows = value as Array<Record<string, unknown>>
    return [columns.join(','), ...rows.map((r) => columns.map((c) => String(r[c] ?? '')).join(','))].join('\n')
  }
})

const Rows = jsonSchema<Array<{ id: number; email: string }>>({
  type: 'array',
  items: {
    type: 'object',
    properties: { id: { type: 'integer' }, email: { type: 'string' } },
    required: ['id', 'email'],
  },
})

const PAYLOAD = [
  { id: 1, email: 'ada@example.com' },
  { id: 2, email: 'grace@example.com' },
  { id: 3, email: 'alan@example.com' },
]

type App = ReturnType<typeof createApp>

function plainApp(): App {
  const app = createApp({ router: new ZenRouter(), pathParser, logger: silent })
  app.get('/rows', { response: { 200: Rows } }, () => PAYLOAD as never)
  return app
}

function negotiatedApp(): App {
  const app = createApp({ router: new ZenRouter(), pathParser, logger: silent })
  app.get('/rows', {
    response: { 200: { 'application/json': Rows, 'text/csv': Rows } },
  }, () => PAYLOAD as never)
  return app
}

const REPS = 9
const ITERATIONS = 20_000

type Call = () => Promise<unknown>
type Injectable = { inject: (m: string, u: string, i?: { headers?: Record<string, string> }) => Promise<unknown> }

/**
 * Paired comparison — the only honest way to compare two arms at this scale.
 *
 * Copied deliberately from `benchmarks/middleware/run.ts`, including the
 * reasoning: each app compiles its own pipeline, so V8 tiers them
 * independently and whichever ran first is measured under different conditions.
 * Alternating the arms inside every rep and reporting the median of the per-rep
 * differences makes the drift common-mode.
 */
async function compare(a: Call, b: Call): Promise<{ a: number; b: number; delta: number; noise: number }> {
  for (let i = 0; i < 5_000; i++) { await a(); await b() }

  const aTimes: number[] = []
  const bTimes: number[] = []
  const deltas: number[] = []

  for (let rep = 0; rep < REPS; rep++) {
    const first = rep % 2 === 0 ? a : b
    const second = rep % 2 === 0 ? b : a

    const t0 = process.hrtime.bigint()
    for (let i = 0; i < ITERATIONS; i++) await first()
    const t1 = process.hrtime.bigint()
    for (let i = 0; i < ITERATIONS; i++) await second()
    const t2 = process.hrtime.bigint()

    const firstUs = Number(t1 - t0) / 1e3 / ITERATIONS
    const secondUs = Number(t2 - t1) / 1e3 / ITERATIONS
    const aUs = rep % 2 === 0 ? firstUs : secondUs
    const bUs = rep % 2 === 0 ? secondUs : firstUs

    aTimes.push(aUs)
    bTimes.push(bUs)
    deltas.push(bUs - aUs)
  }

  const sorted = [...deltas].sort((x, y) => x - y)
  return {
    a: Math.min(...aTimes),
    b: Math.min(...bTimes),
    delta: sorted[Math.floor(sorted.length / 2)] as number,
    noise: ((sorted[sorted.length - 1] as number) - (sorted[0] as number)) / 2,
  }
}

/** Synchronous best-of-N, for the parts of a request that are not a request. */
function timeSync(fn: () => unknown, iterations = 200_000): number {
  for (let i = 0; i < 50_000; i++) fn()
  let best = Infinity
  for (let rep = 0; rep < REPS; rep++) {
    const start = process.hrtime.bigint()
    for (let i = 0; i < iterations; i++) fn()
    best = Math.min(best, Number(process.hrtime.bigint() - start) / 1e3 / iterations)
  }
  return best
}

const verdict = (delta: number, noise: number): string =>
  Math.abs(delta) <= noise ? '   INSIDE NOISE' : ''

function pipelineSource(app: App, method: string, path: string): string {
  return (app as unknown as { generatedSource(): readonly { name: string; source: string }[] })
    .generatedSource()
    .find((u) => u.name === `pipeline:${method}_${path}`)?.source ?? ''
}

const withAccept = (app: Injectable, accept?: string): Call => () =>
  app.inject('GET', '/rows', accept === undefined ? {} : { headers: { accept } })

console.log('\n  Content negotiation — rfcs/0001 §13.4')
console.log('  node ' + process.version + '\n')

// ── 1. the zero-cost gate ───────────────────────────────────────────────────

console.log('  1. A route that declares one representation\n')

{
  const bare = plainApp()
  await bare.ready()

  // A negotiated route in the same process: the module is loaded, an encoder is
  // registered, a negotiator is built. None of it may reach the plain route.
  const alongside = createApp({ router: new ZenRouter(), pathParser, logger: silent })
  alongside.get('/rows', { response: { 200: Rows } }, () => PAYLOAD as never)
  alongside.get('/negotiated', {
    response: { 200: { 'application/json': Rows, 'text/csv': Rows } },
  }, () => PAYLOAD as never)
  await alongside.ready()

  const bareSource = pipelineSource(bare, 'GET', '/rows')
  const alongsideSource = pipelineSource(alongside, 'GET', '/rows')

  console.log(`    pipeline, no negotiated route      ${String(bareSource.length).padStart(5)} bytes`)
  console.log(`    pipeline, one alongside it         ${String(alongsideSource.length).padStart(5)} bytes`)
  console.log(`    byte-identical: ${bareSource === alongsideSource ? 'yes' : 'NO'}`)

  if (bareSource !== alongsideSource || bareSource.length === 0) {
    console.error('\n    ::error:: a route that declares one representation paid for negotiation (§9.4)')
    process.exitCode = 1
  }

  const negotiated = negotiatedApp()
  await negotiated.ready()
  const negotiatedSource = pipelineSource(negotiated, 'GET', '/rows')
  console.log(`    pipeline, negotiated               ${String(negotiatedSource.length).padStart(5)} bytes  (+1 call site, +1 binding)`)

  for (const [needle, where] of [['d.negotiate(ctx)', 'the step'], ['attachNegotiated', 'the binding']] as const) {
    if (bareSource.includes(needle)) {
      console.error(`    ::error:: ${where} was emitted into a route that does not negotiate`)
      process.exitCode = 1
    }
  }
}

// ── 2. per-request cost by Accept shape ─────────────────────────────────────

console.log('\n  2. Marginal cost per request, paired against the same route declared plainly\n')

{
  const plain = plainApp()
  const negotiated = negotiatedApp()
  await plain.ready()
  await negotiated.ready()

  const shapes: Array<[string, string | undefined]> = [
    ['no Accept header', undefined],
    ['Accept: application/json', JSON_MEDIA],
    ['Accept: */*', '*/*'],
    ['Accept: text/csv', CSV],
    ['a browser header, parsed', 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'],
  ]

  for (const [label, accept] of shapes) {
    const result = await compare(
      withAccept(plain as unknown as Injectable, accept),
      withAccept(negotiated as unknown as Injectable, accept),
    )
    console.log(
      `    ${label.padEnd(34)} ${result.a.toFixed(2)} → ${result.b.toFixed(2)} µs   ` +
      `${result.delta >= 0 ? '+' : ''}${result.delta.toFixed(2)} µs  ±${result.noise.toFixed(2)}${verdict(result.delta, result.noise)}`,
    )
  }

  console.log('\n    The last row is the only one that parses. It is also the only one a')
  console.log('    browser sends, which is why the shortcuts above it are worth measuring')
  console.log('    rather than assuming — see section 3.')
}

// ── 3. do the fast paths pay? ───────────────────────────────────────────────

console.log('\n  3. The three shortcuts ahead of the cache\n')

{
  const medias = [JSON_MEDIA, CSV]
  const representations = new Map<string, Representation>(medias.map((media) => [media, {
    media, contentType: `${media}; charset=utf-8`, statuses: new Set([200]), writers: new Map(),
  }]))
  const offers = offersOf(medias)
  const negotiate = makeNegotiator(medias, representations)

  const shapes: Array<[string, string | undefined]> = [
    ['no Accept header', undefined],
    ['exactly a declared type', JSON_MEDIA],
    ['a bare wildcard', '*/*'],
    ['a browser header', 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'],
    ['an unsatisfiable type', 'application/pdf'],
  ]

  for (const [label, accept] of shapes) {
    const viaNegotiator = timeSync(() => negotiate(accept))
    const viaDefinition = accept === undefined
      ? viaNegotiator
      : timeSync(() => selectOffer(accept, offers))
    const note = accept === undefined
      ? 'no definition arm — an absent header never reaches the matcher'
      : `${(viaDefinition / viaNegotiator).toFixed(1)}× faster than parsing`
    console.log(
      `    ${label.padEnd(28)} ${(viaNegotiator * 1000).toFixed(0).padStart(4)} ns   ` +
      `definition ${(viaDefinition * 1000).toFixed(0).padStart(5)} ns   ${note}`,
    )
  }

  const parseOnly = timeSync(() => parseAccept('text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'))
  console.log(`\n    parsing that header alone    ${(parseOnly * 1000).toFixed(0).padStart(4)} ns — the cost the shortcuts and the cache avoid`)
}

// ── 4. does the cache pay? ──────────────────────────────────────────────────

console.log('\n  4. The cache, on the one shape that reaches it\n')

{
  const medias = [JSON_MEDIA, CSV]
  const representations = new Map<string, Representation>(medias.map((media) => [media, {
    media, contentType: `${media}; charset=utf-8`, statuses: new Set([200]), writers: new Map(),
  }]))
  const offers = offersOf(medias)
  const negotiate = makeNegotiator(medias, representations)
  const BROWSER = 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'

  const cached = timeSync(() => negotiate(BROWSER))
  const uncached = timeSync(() => selectOffer(BROWSER, offers))

  console.log(`    cached                       ${(cached * 1000).toFixed(0).padStart(4)} ns`)
  console.log(`    parsed every time            ${(uncached * 1000).toFixed(0).padStart(4)} ns`)
  console.log(`    ratio                        ${(uncached / cached).toFixed(1)}×`)

  // Two distinct headers alternating: the shape a real service sees when a
  // browser and an SDK are both talking to it.
  const alternating = timeSync((() => {
    let i = 0
    return () => negotiate(i++ % 2 === 0 ? BROWSER : 'application/xml;q=0.9, text/csv')
  })())
  console.log(`    two headers, alternating     ${(alternating * 1000).toFixed(0).padStart(4)} ns   both resident`)

  // The pathological case: every request a new key, so every request is a miss
  // *and* pays the bookkeeping. This is the number that says whether the cache
  // is a liability under attack.
  //
  // The headers are built up front and the arms are the *same* strings, because
  // the first version of this measurement got both wrong: it built a template
  // literal inside the timed loop, and it compared a five-range header against
  // the four-range one above. It reported 2.1 µs, of which a good part was
  // string construction and one extra range. The rule from §28.9 applies to a
  // benchmark's own arms as much as to its framing — only compare numbers that
  // came out of the same shape of work.
  const POOL = 4_096
  const misses: string[] = []
  for (let i = 0; i < POOL; i++) {
    misses.push(`text/html,application/xhtml+xml,application/x-${i};q=0.9,*/*;q=0.8`)
  }

  let n = 0
  const thrashing = timeSync(() => negotiate(misses[n++ % POOL] as string), 100_000)
  let m = 0
  const thrashingDefinition = timeSync(() => selectOffer(misses[m++ % POOL] as string, offers), 100_000)

  console.log(`    a new header every request   ${(thrashing * 1000).toFixed(0).padStart(4)} ns   every one a miss`)
  console.log(`    the same, with no cache      ${(thrashingDefinition * 1000).toFixed(0).padStart(4)} ns   the bookkeeping is the difference`)

  console.log('\n    Read the last two rows together: the cache costs about')
  console.log(`    ${((thrashing - thrashingDefinition) * 1000).toFixed(0)} ns when it never hits, and saves about ${((uncached - cached) * 1000).toFixed(0)} ns when it does.`)
  console.log('    That is the trade, stated rather than asserted, and it is why the limit')
  console.log('    is 32 and the policy on overflow is to give up rather than to rank.')
}

// ── 5. what a 406 costs ─────────────────────────────────────────────────────

console.log('\n  5. Refusing, against the response it would otherwise have been\n')

{
  const negotiated = negotiatedApp()
  await negotiated.ready()
  const injectable = negotiated as unknown as Injectable

  const result = await compare(
    withAccept(injectable, JSON_MEDIA),
    withAccept(injectable, 'application/pdf'),
  )

  console.log(`    a served 200                 ${result.a.toFixed(2)} µs`)
  console.log(`    a refused 406                ${result.b.toFixed(2)} µs   ${(result.b / result.a).toFixed(1)}× more expensive`)

  console.log('\n    Not a negotiation cost. The matcher answered in the nanoseconds measured')
  console.log('    in section 3; the rest is building the error and rendering a problem')
  console.log('    document. This ratio was 13× when §13.4 was built, almost all of it the')
  console.log('    stack of an `Error` nobody would read; a 406 is now built without one')
  console.log('    (§28.8, `withoutStack`), and `benchmarks/refusals` gates that it stays so.')
}

// ── 6. the security gate ────────────────────────────────────────────────────

console.log('\n  6. A representation the client refused is never served — gate\n')

{
  const shapes: Array<[string, string[]]> = [
    ['two types', [JSON_MEDIA, CSV]],
    ['reverse order', [CSV, JSON_MEDIA]],
    ['one type', [JSON_MEDIA]],
    ['three types', [JSON_MEDIA, CSV, 'application/xml']],
    ['a vendor type', ['application/vnd.acme.v2+json', JSON_MEDIA]],
  ]

  // Each header names something and refuses it. Serving the refused thing is
  // the defect; a 406, or serving something else, is correct.
  const hostile: Array<[string, string]> = [
    ['application/json;q=0', JSON_MEDIA],
    ['application/json;q=0, */*', JSON_MEDIA],
    ['text/csv;q=0, */*', CSV],
    ['application/*;q=0, */*', JSON_MEDIA],
    ['*/*;q=0', JSON_MEDIA],
    ['*/*;q=0, text/csv;q=0', CSV],
    ['application/json;q=0.0', JSON_MEDIA],
    ['application/json;q=0, application/json;q=0', JSON_MEDIA],
  ]

  let served = 0
  for (const [label, medias] of shapes) {
    const representations = new Map<string, Representation>(medias.map((media) => [media, {
      media, contentType: media, statuses: new Set([200]), writers: new Map(),
    }]))
    const negotiate = makeNegotiator(medias, representations)

    let violations = 0
    for (const [header, refused] of hostile) {
      if (!medias.includes(refused)) continue
      // Twice: cold, then warm, because a cache is a second chance to be wrong.
      for (const chosen of [negotiate(header), negotiate(header)]) {
        if (chosen !== null && chosen.media === refused) {
          violations++
          console.error(`    ::error:: ${label} served ${refused} for ${JSON.stringify(header)}`)
        }
      }
    }
    served += violations
    console.log(`    ${label.padEnd(18)} ${hostile.length * 2} hostile headers   ${violations === 0 ? 'none served' : `${violations} SERVED`}`)
  }

  if (served > 0) {
    console.error('\n    ::error:: a representation the client explicitly refused was served (§13.4)')
    process.exitCode = 1
  } else {
    console.log('\n    In a benchmark rather than only in the test suite because "serve the first')
    console.log('    thing we have" is the fastest possible negotiation, and scoring by the')
    console.log('    highest q rather than the most specific range is the shortcut that')
    console.log('    silently produces exactly this defect.')
  }
}

// ── 7. the cache is bounded ─────────────────────────────────────────────────

console.log('\n  7. The cache under attacker-chosen keys — gate\n')

{
  const medias = [JSON_MEDIA, CSV]
  const representations = new Map<string, Representation>(medias.map((media) => [media, {
    media, contentType: media, statuses: new Set([200]), writers: new Map(),
  }]))
  const negotiate = makeNegotiator(medias, representations)
  const offers = offersOf(medias)

  // Built up front: a template literal inside the timed loop measures string
  // construction, and the point of this gate is what the *cache* costs when
  // every key is new.
  const DISTINCT = 200_000
  const headers: string[] = []
  for (let i = 0; i < DISTINCT; i++) headers.push(`application/x-${i};q=0.3, text/csv;q=0.9`)

  const start = process.hrtime.bigint()
  for (let i = 0; i < DISTINCT; i++) negotiate(headers[i] as string)
  const elapsed = Number(process.hrtime.bigint() - start) / 1e6

  console.log(`    ${DISTINCT} distinct Accept headers      ${elapsed.toFixed(0)} ms   ${(elapsed * 1e6 / DISTINCT).toFixed(0)} ns each`)
  console.log(`    cache limit                        ${NEGOTIATION_CACHE_LIMIT} entries`)

  // Correctness after the abuse: a bounded cache that answers wrongly once full
  // is worse than no cache.
  const after = negotiate('text/csv')
  const definition = selectOffer('text/csv', offers)
  if (after === null || after.media !== medias[definition]) {
    console.error('\n    ::error:: the cache answered incorrectly after being thrashed (§13.4)')
    process.exitCode = 1
  } else {
    console.log('    still correct afterwards           yes')
  }

  const perRequest = elapsed * 1e6 / DISTINCT
  if (perRequest > 5_000) {
    console.error(`\n    ::error:: ${perRequest.toFixed(0)} ns per attacker-chosen header — the cache is an amplifier, not a cache`)
    process.exitCode = 1
  }

  console.log('\n    One cold pass, not a best-of-nine, and every key genuinely distinct, so')
  console.log("    this is higher than section 4's miss and is not comparable to it — only")
  console.log('    subtract numbers that came out of the same pairing. It is the one that')
  console.log('    matters here, because an attacker does not warm anything up.')
}

console.log()
